/// Streaming FNV-1a. Folds a value at a time so nothing is buffered.
class Hasher
{
public:
    /// Presence and union discriminators are folded through this, so an absent
    /// field and a field holding the tag's value cannot collide.
    void tag(uint8_t value)
    {
        _state ^= value;
        _state *= PRIME;
    }

    template <typename TValue>
    void raw(TValue value)
    {
        static_assert(std::is_trivially_copyable_v<TValue>);
        uint8_t bytes[sizeof(TValue)];
        __builtin_memcpy(bytes, &value, sizeof(TValue));
        for(uint8_t byte : bytes)
        {
            tag(byte);
        }
    }

    uint64_t value() const
    {
        return _state;
    }

private:
    static constexpr uint64_t OFFSET_BASIS = 0xcbf29ce484222325ULL;
    static constexpr uint64_t PRIME        = 0x100000001b3ULL;

    uint64_t _state = OFFSET_BASIS;
};

/// Resolves a tensor uid to its ordinal in the domain vector, so the key
/// folds structure rather than caller-assigned labels.
///
/// Non-owning view over the caller's vector; the traversal must not
/// outlive it.
class UidCanon
{
public:
    UidCanon() = default;

    /// A resolved reference carries its ordinal; an unresolved one
    /// carries the raw uid instead. `resolved` is folded and compared
    /// ahead of `value`, distinguishing a resolved ordinal from a
    /// dangling reference to the same number.
    struct Fold
    {
        bool resolved;
        int64_t value;
    };

    using Domain = ::flatbuffers::Vector<::flatbuffers::Offset<TensorAttributes>>;

    explicit UidCanon(const Domain* domain)
        : _domain(domain)
    {
    }

    /// Linear scan: the vector is small and this keeps the traversal
    /// allocation-free.
    Fold operator()(int64_t uid) const
    {
        if(_domain != nullptr)
        {
            for(uint32_t index = 0; index < _domain->size(); ++index)
            {
                if(_domain->Get(index)->uid() == uid)
                {
                    return Fold{true, static_cast<int64_t>(index)};
                }
            }
        }
        return Fold{false, uid};
    }

private:
    const Domain* _domain = nullptr;
};

