inline void hashAppend(Hasher& hasher, const TensorAttributes* value, const UidCanon& canon)
{
    if(value == nullptr)
    {
        hasher.tag(0);
        return;
    }
    hasher.tag(1);
    hasher.raw(static_cast<int64_t>(value->data_type()));
    {
        const auto* items = value->strides();
        const uint32_t count = items == nullptr ? 0u : items->size();
        // Length first: {1, 2} and {1, 2, 0} must not fold alike.
        hasher.raw(count);
        for(uint32_t index = 0; index < count; ++index)
        {
            hasher.raw(items->Get(index));
        }
    }
    {
        const auto* items = value->dims();
        const uint32_t count = items == nullptr ? 0u : items->size();
        // Length first: {1, 2} and {1, 2, 0} must not fold alike.
        hasher.raw(count);
        for(uint32_t index = 0; index < count; ++index)
        {
            hasher.raw(items->Get(index));
        }
    }
    hasher.raw(value->virtual_());
    hashAppend(hasher, value->value_type(), value->value(), canon);
    hasher.raw(value->is_runtime_pass_by_value());
    {
        const auto optional = value->ragged_offset_tensor_uid();
        hasher.tag(optional ? 1 : 0);
        if(optional)
        {
            hashAppend(hasher, canon(*optional));
        }
    }
    hasher.raw(value->alignment());
}

inline bool logicallyEqual(const TensorAttributes* a, const TensorAttributes* b, const UidCanon& aCanon, const UidCanon& bCanon)
{
    if(a == b)
    {
        return true;
    }
    if(a == nullptr || b == nullptr)
    {
        return false;
    }
    if(a->data_type() != b->data_type())
    {
        return false;
    }
    {
        const auto* aItems = a->strides();
        const auto* bItems = b->strides();
        const uint32_t aCount = aItems == nullptr ? 0u : aItems->size();
        const uint32_t bCount = bItems == nullptr ? 0u : bItems->size();
        if(aCount != bCount)
        {
            return false;
        }
        for(uint32_t index = 0; index < aCount; ++index)
        {
            if(aItems->Get(index) != bItems->Get(index))
            {
                return false;
            }
        }
    }
    {
        const auto* aItems = a->dims();
        const auto* bItems = b->dims();
        const uint32_t aCount = aItems == nullptr ? 0u : aItems->size();
        const uint32_t bCount = bItems == nullptr ? 0u : bItems->size();
        if(aCount != bCount)
        {
            return false;
        }
        for(uint32_t index = 0; index < aCount; ++index)
        {
            if(aItems->Get(index) != bItems->Get(index))
            {
                return false;
            }
        }
    }
    if(a->virtual_() != b->virtual_())
    {
        return false;
    }
    if(!logicallyEqual(a->value_type(), a->value(), b->value_type(), b->value(), aCanon, bCanon))
    {
        return false;
    }
    if(a->is_runtime_pass_by_value() != b->is_runtime_pass_by_value())
    {
        return false;
    }
    {
        const auto aUid = a->ragged_offset_tensor_uid();
        const auto bUid = b->ragged_offset_tensor_uid();
        if(aUid.has_value() != bUid.has_value())
        {
            return false;
        }
        if(aUid.has_value() && aCanon(*aUid) != bCanon(*bUid))
        {
            return false;
        }
    }
    if(a->alignment() != b->alignment())
    {
        return false;
    }
    return true;
}

inline void hashAppend(Hasher& hasher, const Graph* value)
{
    hashAppend(hasher, value, UidCanon{value == nullptr ? nullptr : value->tensors()});
}

inline bool logicallyEqual(const Graph* a, const Graph* b)
{
    return logicallyEqual(a, b, UidCanon{a == nullptr ? nullptr : a->tensors()}, UidCanon{b == nullptr ? nullptr : b->tensors()});
}

